head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL16613";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16613.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $c.util.getComponent("txt_printArea").setValue(({ innerHTML: (scwin.openerComp("printme").getValue ? scwin.openerComp("printme").getValue() : (console.warn('[sdd] 부모 내용 읽기 미해결(컴포넌트/게터 부재): ' + ("printme")), '')), innerText: (scwin.openerComp("printme").getValue ? scwin.openerComp("printme").getValue() : (console.warn('[sdd] 부모 내용 읽기 미해결(컴포넌트/게터 부재): ' + ("printme")), '')), value: (scwin.openerComp("printme").getValue ? scwin.openerComp("printme").getValue() : (console.warn('[sdd] 부모 내용 읽기 미해결(컴포넌트/게터 부재): ' + ("printme")), '')) }).innerHTML);
        scwin.PopupAutoResizeBy();
        await $c.win.print();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16613.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name PopupAutoResizeBy
 * @description Popup Auto Resize By 처리
 * @returns {void}
 * @hidden N
 */
scwin.PopupAutoResizeBy = function () {

    let mw = 0;
    let mh = 0;
    if (innerWidth && innerHeight) {
        mw = outerWidth - innerWidth + 100;
        mh = outerHeight - innerHeight + 10;

    } else {
        mw = $(document).outerWidth() - $(window).width() + 100;
        mh = $(document).outerHeight() - $(window).height() + 10;
        if (navigator.userAgent.indexOf("MSIE 8") > 0) {
            mh = mh - 20;
        }
        if (navigator.userAgent.indexOf("MSIE 7") > 0) {
            mh = mh - 20;
        }
        window.resizeBy(mw, mh);
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerComp
 * @description 부모 화면 컴포넌트(as-is opener.document.<폼>.<필드>). 부모·컴포넌트가 없으면 빈 객체(메서드 존재 검사로 건너뛴다)
 * @param {*} id 부모 화면 컴포넌트 id
 * @returns {Object} 컴포넌트 또는 {}
 * @hidden N
 */
scwin.openerComp = function (id) {
    return scwin.opener().getComponentById(id) || {};
};
